package com.bananalab.lite;
import android.app.*;import android.widget.*;import android.graphics.Color;
/** Inline character controls; all commits pass through BananaProject. */
final class BananaEditor extends LinearLayout{
 interface Host{boolean locked();void edited(String message,String actor);void importReference(SceneDraft expected,String actor,boolean remove);}
 private final Activity activity;private final Host host;private SceneDraft expected;private String id;private final TextView info;private final CheckBox remove;
 BananaEditor(Activity a,SceneDraft draft,String actor,Host h)throws Exception{super(a);activity=a;host=h;expected=draft.copy();id=expected.get(actor)!=null?actor:expected.get(expected.focused)!=null?expected.focused:expected.cast.get(0).name;setOrientation(1);setPadding(10,10,10,10);setBackgroundColor(0xff303e4d);TextView label=new TextView(a);label.setText("Editar personaje");label.setTextColor(Color.WHITE);addView(label);
  Spinner who=new Spinner(a);String[] names=new String[expected.cast.size()];for(int i=0;i<names.length;i++)names[i]=expected.cast.get(i).display();who.setAdapter(new ArrayAdapter<String>(a,android.R.layout.simple_spinner_dropdown_item,names){@Override public android.view.View getView(int position,android.view.View convert,android.view.ViewGroup parent){android.view.View v=super.getView(position,convert,parent);((TextView)v).setTextColor(Color.WHITE);return v;}});who.setSelection(expected.cast.indexOf(expected.get(id)));addView(who);info=new TextView(a);info.setTextColor(Color.WHITE);addView(info);who.setOnItemSelectedListener(new android.widget.AdapterView.OnItemSelectedListener(){public void onItemSelected(android.widget.AdapterView<?> p,android.view.View v,int position,long item){id=expected.cast.get(position).name;if(!host.locked()&&!id.equals(expected.focused))try{SceneDraft next=expected.copy();next.focused=id;BananaProject.edit(activity,expected,next);expected=next;}catch(Exception e){error(e);}describe();}public void onNothingSelected(android.widget.AdapterView<?> p){}});
  button("Color",()->pick("Color",new String[]{"amarillo","azul","verde","rojo","rosa","gris","blanco","marron"},value->edit("rojo|roja|azul|verde|amarillo|amarilla|rosa|gris|blanco|marron|negro|violeta|naranja",value)));
  button("Ropa y accesorios",()->pick("Ropa",new String[]{"sin accesorios","sombrero","corona","sobretodo","lentes","sombrero y sobretodo","sombrero y sobretodo y lentes","corona y sobretodo","corona y lentes","sobretodo y lentes"},value->edit("detective|sombrero|corona|sobretodo|gabardina|abrigo|lentes|gafas|anteojos",value.equals("sin accesorios")?"":value.replace(" y "," "))));
  button("Expresión",()->pick("Expresión",new String[]{"feliz","triste","sorprendido"},value->edit("feliz|triste|sorprendido|sorprendida",value)));
  button("Ojos",()->pick("Rasgos",new String[]{"ojos normales","ojos pequenos","ojos grandes"},value->edit("ojos (?:normales|pequenos|chicos|grandes)",value)));
  button("Proporciones",()->pick("Proporciones",new String[]{"normal","alto","bajo","ancho","delgado"},value->edit("alto|alta|bajo|baja|ancho|ancha|delgado|delgada|alargado|alargada|gordo|gorda|fino|fina|corto|corta",value.equals("normal")?"":value)));
  button("Voz sintética",()->pick("Voz sintética experimental",new String[]{"media","grave","aguda","robotica"},value->{try{SceneDraft next=expected.copy();next.get(id).voice=value;SceneTiming.fit(next);save(next);}catch(Exception e){error(e);}}));
  button("Forma de criatura",()->pick("Forma (solo criaturas)",new String[]{"redondo","ovalado","cuadrado","estrella","gota","capsula"},value->{if(!expected.get(id).kind.equals("criatura")){info.setText("Creá una criatura para combinar cuerpo, orejas y cola.");return;}edit("redondo|redonda|ovalado|ovalada|cuadrado|cuadrada|estrella|gota|capsula",value);}));
  button("Orejas de criatura",()->pick("Orejas",new String[]{"sin orejas","orejas redondas","orejas largas","orejas puntiagudas"},value->{if(expected.get(id).kind.equals("criatura"))edit("sin orejas|orejas (?:redondas|largas|puntiagudas)",value);}));
  button("Cola de criatura",()->pick("Cola",new String[]{"sin cola","cola corta","cola larga"},value->{if(expected.get(id).kind.equals("criatura"))edit("sin cola|cola (?:corta|larga)",value);}));
  button("Vista",()->pick("Vista",new String[]{"frente","perfil derecho","perfil izquierdo","espalda"},value->{try{SceneDraft next=expected.copy();next.get(id).view=value.equals("frente")?"front":value.equals("espalda")?"back":value.contains("izquierdo")?"left":"right";save(next);}catch(Exception e){error(e);}}));
  remove=new CheckBox(a);remove.setText("Quitar fondo uniforme");remove.setTextColor(Color.WHITE);addView(remove);button("Importar referencia",()->{if(!host.locked())host.importReference(expected,id,remove.isChecked());});button("Volver al diseño generado",()->{try{if(host.locked())return;SceneDraft next=expected.copy();next.get(id).reference="";save(next);}catch(Exception e){error(e);}});describe();
 }
 interface Pick{void value(String v);}private void pick(String title,String[] values,Pick action){if(host.locked())return;if(!expected.get(id).reference.isEmpty()){info.setText("La referencia se conserva completa. Volvé al diseño generado para modificarla.");return;}UiTypeface.show(new AlertDialog.Builder(activity).setTitle(title).setItems(values,(d,i)->action.value(values[i])));}
 private void button(String text,Runnable action){Button b=new Button(activity);b.setText(text);b.setAllCaps(false);addView(b);b.setOnClickListener(v->action.run());}
 private void edit(String category,String value){try{SceneDraft next=expected.copy();next.get(id).look=SceneDirector.replace(next.get(id).look,category,value);save(next);}catch(Exception e){error(e);}}
 private void save(SceneDraft next)throws Exception{if(host.locked())return;next.focused=id;BananaProject.edit(activity,expected,next);host.edited("Actualicé el diseño de "+next.get(id).display()+".",id);}
 private void describe(){SceneDraft.Actor a=expected.get(id);info.setText(a.display()+" · "+a.kind+" · "+(a.look.isEmpty()?"aspecto original":a.look)+(a.reference.isEmpty()?"":" · referencia conservada"));}
 private void error(Exception e){info.setText(e.getMessage());}
}
